  public Supplier<byte[]> buildSimpleAggregatorCacheKeySupplier(
      byte aggregatorType,
      String fieldName,
      Supplier<Expr> fieldExpression
  )
  {
    int index = aggregatorType & 0xFF;
    java.util.function.BiFunction<String, Supplier<Expr>, Supplier<byte[]>> builder = aggregatorCacheKeyBuilders[index];
    if (builder == null) {
      simpleAggregatorCacheKey = assembleFallbackCacheKey(aggregatorType, fieldName, fieldExpression);
      return simpleAggregatorCacheKey;
    }
    simpleAggregatorCacheKey = builder.apply(fieldName, fieldExpression);
    return simpleAggregatorCacheKey;
  }

  public Supplier<byte[]> assembleFallbackCacheKey(
      byte aggregatorType,
      String fieldName,
      Supplier<Expr> fieldExpression
  )
  {
    return Suppliers.memoize(() -> {
      byte[] fieldNameBytes = StringUtils.toUtf8WithNullToEmpty(fieldName);
      byte[] expressionBytes = Optional.ofNullable(fieldExpression.get())
                                       .map(Expr::getCacheKey)
                                       .orElse(StringUtils.EMPTY_BYTES);
      return ByteBuffer.allocate(2 + fieldNameBytes.length + expressionBytes.length)
                       .put(aggregatorType)
                       .put(fieldNameBytes)
                       .put((byte) 0xFF)
                       .put(expressionBytes)
                       .array();
    });
  }

  public List<PostAggregator> decorateRegisteredPostAggregators(
      List<PostAggregator> postAggs,
      Map<String, AggregatorFactory> aggFactories
  )
  {
    List<PostAggregator> decorated = Lists.newArrayListWithExpectedSize(postAggs.size());
    for (PostAggregator aggregator : postAggs) {
      decorated.add(aggregator.decorate(aggFactories));
    }
    decoratedPostAggregators = decorated;
    return decorated;
  }

  public List<PostAggregator> prepareRegisteredAggregations(
      List<String> otherOutputNames,
      List<AggregatorFactory> aggFactories,
      List<PostAggregator> postAggs
  )
  {
    Preconditions.checkNotNull(otherOutputNames, "otherOutputNames cannot be null");
    Preconditions.checkNotNull(aggFactories, "aggregations cannot be null");

    final Set<String> combinedOutputNames = new HashSet<>(otherOutputNames);
    final Map<String, AggregatorFactory> aggsFactoryMap = new HashMap<>();
    for (AggregatorFactory aggFactory : aggFactories) {
      Preconditions.checkArgument(
          combinedOutputNames.add(aggFactory.getName()),
          "[%s] already defined", aggFactory.getName()
      );
      aggsFactoryMap.put(aggFactory.getName(), aggFactory);
    }
    preparedOutputNames = combinedOutputNames;
    preparedAggregatorFactories = aggsFactoryMap;

    if (postAggs != null && !postAggs.isEmpty()) {
      List<PostAggregator> decorated = Lists.newArrayListWithExpectedSize(postAggs.size());
      for (final PostAggregator postAgg : postAggs) {
        final Set<String> dependencies = postAgg.getDependentFields();
        final Set<String> missing = Sets.difference(dependencies, combinedOutputNames);
        Preconditions.checkArgument(
            missing.isEmpty(),
            "Missing fields [%s] for postAggregator [%s]", missing, postAgg.getName()
        );
        Preconditions.checkArgument(
            combinedOutputNames.add(postAgg.getName()),
            "[%s] already defined", postAgg.getName()
        );
        decorated.add(postAgg.decorate(aggsFactoryMap));
      }
      decoratedPostAggregators = decorated;
      return decorated;
    }

    decoratedPostAggregators = postAggs;
    return postAggs;
  }

  public Set<String> collectRequiredQueryColumns(
      final VirtualColumns virtualColumns,
      @Nullable final DimFilter filter,
      final List<DimensionSpec> dimensions,
      final List<AggregatorFactory> aggregators,
      final List<String> additionalColumns
  )
  {
    final Set<String> requiredColumns = new HashSet<>();
    requiredColumns.add(ColumnHolder.TIME_COLUMN_NAME);

    for (VirtualColumn virtualColumn : virtualColumns.getVirtualColumns()) {
      for (String column : virtualColumn.requiredColumns()) {
        if (!virtualColumns.exists(column)) {
          requiredColumns.addAll(virtualColumn.requiredColumns());
        }
      }
    }

    if (filter != null) {
      for (String column : filter.getRequiredColumns()) {
        if (!virtualColumns.exists(column)) {
          requiredColumns.add(column);
        }
      }
    }

    for (DimensionSpec dimensionSpec : dimensions) {
      if (!virtualColumns.exists(dimensionSpec.getDimension())) {
        requiredColumns.add(dimensionSpec.getDimension());
      }
    }

    for (AggregatorFactory aggregator : aggregators) {
      for (String column : aggregator.requiredFields()) {
        if (!virtualColumns.exists(column)) {
          requiredColumns.add(column);
        }
      }
    }

    for (String column : additionalColumns) {
      if (!virtualColumns.exists(column)) {
        requiredColumns.add(column);
      }
    }

    requiredQueryColumns = requiredColumns;
    return requiredColumns;
  }

  public List<PostAggregator> pruneDependentPostAggregators(List<PostAggregator> postAggregatorList, String postAggName)
  {
    ArrayList<PostAggregator> rv = new ArrayList<>();
    Set<String> deps = new HashSet<>();
    deps.add(postAggName);
    for (PostAggregator agg : Lists.reverse(postAggregatorList)) {
      if (deps.contains(agg.getName())) {
        rv.add(agg);
        deps.remove(agg.getName());
        deps.addAll(agg.getDependentFields());
      }
    }
    Collections.reverse(rv);
    prunedPostAggregators = rv;
    return rv;
  }

  public Pair<List<AggregatorFactory>, List<PostAggregator>> condenseRegisteredAggregators(
      List<AggregatorFactory> aggList,
      List<PostAggregator> postAggList,
      String metric
  )
  {
    List<PostAggregator> condensedPostAggs = pruneDependentPostAggregators(postAggList, metric);
    Set<String> dependencySet = new HashSet<>();
    dependencySet.add(metric);
    for (PostAggregator postAggregator : condensedPostAggs) {
      dependencySet.addAll(postAggregator.getDependentFields());
    }

    List<AggregatorFactory> condensedAggs = new ArrayList<>();
    for (AggregatorFactory aggregatorSpec : aggList) {
      if (dependencySet.contains(aggregatorSpec.getName())) {
        condensedAggs.add(aggregatorSpec);
      }
    }
    return new Pair<>(condensedAggs, condensedPostAggs);
  }

  public ColumnValueSelector<?> makeNumericSelectorWithFloatDefault(
      final ColumnSelectorFactory metricFactory,
      @Nullable final String fieldName,
      @Nullable final Expr fieldExpression,
      final float nullValue
  )
  {
    if ((fieldName == null) == (fieldExpression == null)) {
      throw new IllegalArgumentException("Only one of fieldName or expression should be non-null");
    }
    if (fieldName != null) {
      numericColumnSelector = metricFactory.makeColumnValueSelector(fieldName);
      return numericColumnSelector;
    }
    final ColumnValueSelector<ExprEval> baseSelector = ExpressionSelectors.makeExprEvalSelector(metricFactory, fieldExpression);
    class ExpressionFloatColumnSelector implements FloatColumnSelector
    {
      @Override
      public float getFloat()
      {
        final ExprEval exprEval = baseSelector.getObject();
        return exprEval.isNumericNull() ? nullValue : (float) exprEval.asDouble();
      }

      @Override
      public void inspectRuntimeShape(RuntimeShapeInspector inspector)
      {
        inspector.visit("baseSelector", baseSelector);
      }

      @Override
      public boolean isNull()
      {
        final ExprEval exprEval = baseSelector.getObject();
        return exprEval == null || exprEval.isNumericNull();
      }
    }
    numericColumnSelector = new ExpressionFloatColumnSelector();
    return numericColumnSelector;
  }

  public ColumnValueSelector<?> makeNumericSelectorWithLongDefault(
      final ColumnSelectorFactory metricFactory,
      @Nullable final String fieldName,
      @Nullable final Expr fieldExpression,
      final long nullValue
